-- Learning Watch | Read lanes (2026-10-25).
--
-- A gap's material is offered in two lanes — Watch (video, course) and Read
-- (doc, roadmap, repo) — and the `courses` quota now counts per lane, per gap
-- (lib/domain/lanes.ts). Docs say whether they are official or a tutorial;
-- courses carry an overview flag and a `checked_at` TTL stamp.
--
-- Generated by `prisma migrate diff` (HEAD schema → this schema), then edited
-- by hand in three places (CLAUDE.md §13 — CHECKs, a partial index and
-- backfills have no Prisma equivalent):
--   1. `learning_steps.lane` is added nullable, backfilled, then SET NOT NULL
--      (generated SQL added it NOT NULL with no default, which fails on any
--      existing row).
--   2. Backfills for `courses.doc_kind`, `courses.checked_at`,
--      `learning_steps.is_primary` and the course caps, each before the
--      constraint that depends on it.
--   3. CHECK `courses_doc_needs_kind`, partial unique index
--      `learning_steps_one_primary`, and the course-cap range CHECKs
--      re-bounded from 0–6 to 0–3.

-- CreateEnum
CREATE TYPE "lane" AS ENUM ('watch', 'read');

-- CreateEnum
CREATE TYPE "doc_kind" AS ENUM ('official', 'tutorial');

-- AlterTable
ALTER TABLE "users" ALTER COLUMN "cap_courses" SET DEFAULT 2;

-- AlterTable
ALTER TABLE "workspace_settings" ALTER COLUMN "cap_courses" SET DEFAULT 2;

-- AlterTable
ALTER TABLE "skill_gaps" ADD COLUMN     "capped_lanes" "lane"[] DEFAULT ARRAY[]::"lane"[];

-- AlterTable (hand-edited: `lane` added nullable here, NOT NULL after backfill)
ALTER TABLE "learning_steps" ADD COLUMN     "is_primary" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "lane" "lane";

-- AlterTable
ALTER TABLE "courses" ADD COLUMN     "checked_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
ADD COLUMN     "doc_kind" "doc_kind",
ADD COLUMN     "is_overview" BOOLEAN NOT NULL DEFAULT false;

-- ---------------------------------------------------------------------------
-- Hand-written below.
-- ---------------------------------------------------------------------------

-- Every doc in the corpus today was curated from official documentation;
-- tutorials arrive with the new ingest, which sets the kind itself.
UPDATE "courses" SET "doc_kind" = 'official' WHERE "type" = 'doc';

-- The last time anyone confirmed a URL is the day it was vetted.
UPDATE "courses" SET "checked_at" = "verified_at"::timestamptz;

-- A doc must say which kind it is; nothing else may carry one implicitly.
ALTER TABLE "courses" ADD CONSTRAINT "courses_doc_needs_kind"
  CHECK ("type" <> 'doc' OR "doc_kind" IS NOT NULL);

-- Each existing step takes its lane from its course (lib/domain/lanes.ts laneOf).
UPDATE "learning_steps" AS s
SET "lane" = CASE WHEN c."type" IN ('video', 'course') THEN 'watch'::"lane" ELSE 'read'::"lane" END
FROM "courses" AS c
WHERE c."id" = s."course_id";

ALTER TABLE "learning_steps" ALTER COLUMN "lane" SET NOT NULL;

-- Each gap leads with its earliest step, and only one.
UPDATE "learning_steps" SET "is_primary" = true
WHERE "id" IN (
  SELECT DISTINCT ON ("gap_id") "id"
  FROM "learning_steps"
  ORDER BY "gap_id", "ordinal", "id"
);

CREATE UNIQUE INDEX "learning_steps_one_primary"
  ON "learning_steps" ("gap_id") WHERE "is_primary";

-- `cap_courses` was per gap (0–6); it is now per lane, per gap (0–3). Halve,
-- rounding up so nobody loses their only item, and clamp to the lane maximum.
-- Old Free 2 / Pro 4 / Ultra 6 become 1 / 2 / 3.
UPDATE "users"              SET "cap_courses" = LEAST(3, CEIL("cap_courses" / 2.0))::int;
UPDATE "workspace_settings" SET "cap_courses" = LEAST(3, CEIL("cap_courses" / 2.0))::int;
UPDATE "plan_configs"       SET "cap_courses" = LEAST(3, CEIL("cap_courses" / 2.0))::int;

ALTER TABLE "users" DROP CONSTRAINT "users_cap_courses_range";
ALTER TABLE "users" ADD CONSTRAINT "users_cap_courses_range"
  CHECK ("cap_courses" BETWEEN 0 AND 3);

ALTER TABLE "workspace_settings" DROP CONSTRAINT "workspace_settings_cap_courses_range";
ALTER TABLE "workspace_settings" ADD CONSTRAINT "workspace_settings_cap_courses_range"
  CHECK ("cap_courses" BETWEEN 0 AND 3);

ALTER TABLE "plan_configs" DROP CONSTRAINT "plan_configs_cap_courses";
ALTER TABLE "plan_configs" ADD CONSTRAINT "plan_configs_cap_courses"
  CHECK ("cap_courses" BETWEEN 0 AND 3);
